def standard():
    from itertools import product
    c = 0
    for t in product(range(1, 7), repeat=3):
        st = [0, 0, 1]
        for k in t:
            if k <= 3:
                st[k - 1] ^= 1
            elif k == 6:
                st = [x ^ 1 for x in st]
        c += (sum(st) == 0)
